def solve(date: str, months: int) -> str:
    def is_leap(year: int) -> bool:
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

    def days_in_month(year: int, month: int) -> int:
        if month == 2:
            return 29 if is_leap(year) else 28
        if month in (4, 6, 9, 11):
            return 30
        return 31

    if months == 0:
        return date

    year, month, day = map(int, date.split("-"))

    total_months = (year - 1) * 12 + (month - 1) + months
    new_year = total_months // 12 + 1
    new_month = total_months % 12 + 1

    if day == days_in_month(year, month):
        new_day = days_in_month(new_year, new_month)
    else:
        new_day = min(day, days_in_month(new_year, new_month))

    return f"{new_year:04d}-{new_month:02d}-{new_day:02d}"

def _is_leap(year: int) -> bool:
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def _last_day(year: int, month: int) -> int:
    if month == 2:
        return 29 if _is_leap(year) else 28
    if month in (4, 6, 9, 11):
        return 30
    return 31


def solve(date: str, months: int) -> str:
    year, month, day = map(int, date.split("-"))

    if months == 0:
        return date

    input_last_day = _last_day(year, month)
    total_months = year * 12 + (month - 1) + months
    dest_year, dest_month_index = divmod(total_months, 12)
