    i = 0
    n = len(text)

    while i < n:
        if text[i] == '"':
            i += 1
            chars = []
            while i < n:
                if text[i] == '"':
                    if i + 1 < n and text[i + 1] == '"':
                        chars.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    chars.append(text[i])
                    i += 1
            field = "".join(chars)
        else:
            start = i
            while i < n and text[i] not in ",\r\n":
                i += 1
            field = text[start:i]

        record.append(field)

        if i >= n:
            records.append(record)
            record = []
            break

        if text[i] == ",":
            i += 1
            if i == n:
                record.append("")
                records.append(record)
                record = []
        elif text[i] == "\n":
            records.append(record)
            record = []
            i += 1
        else:
            records.append(record)
            record = []
            i += 2

    return records

