def _wrap_int32(value: int) -> int:
    value &= 0xFFFFFFFF
    return value if value < 0x80000000 else value - 0x100000000


def solve(program: list[str]) -> list[int] | None:
    stack = []

    for instruction in program:
        if not isinstance(instruction, str):
            return None

        if instruction.startswith("push "):
            operand = instruction[5:]
            if not operand:
                return None

            negative = operand[0] == "-"
            if negative:
                operand = operand[1:]
                if not operand:
                    return None

            value = 0
            for char in operand:
                if char < "0" or char > "9":
                    return None
                value = (value * 10 + (ord(char) - ord("0"))) & 0xFFFFFFFF

            if negative:
                value = (-value) & 0xFFFFFFFF

            stack.append(value if value < 0x80000000 else value - 0x100000000)

        elif instruction == "pop":
            if not stack:
                return None
            stack.pop()

        elif instruction == "dup":
            if not stack:
                return None
            stack.append(stack[-1])

        elif instruction == "swap":
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]

        elif instruction == "neg":
            if not stack:
                return None
            stack[-1] = _wrap_int32(-stack[-1])

        elif instruction in ("add", "sub", "mul", "div", "mod"):
            if len(stack) < 2:
                return None

            b = stack.pop()
            a = stack.pop()

            if instruction == "add":
                result = a + b
            elif instruction == "sub":
                result = a - b
            elif instruction == "mul":
                result = a * b
            else:
                if b == 0:
                    return None

                quotient = abs(a) // abs(b)
                if (a < 0) != (b < 0):
                    quotient = -quotient

                if instruction == "div":
                    result = quotient
                else:
                    result = a - b * quotient

            stack.append(_wrap_int32(result))

        else:
            return None

    return stack

