def solve(grid):
    if not grid or not grid[0]:
        return None

    rows, cols = len(grid), len(grid[0])

    if grid[0][0] is None or grid[-1][-1] is None:
        return None

    best = [[None] * cols for _ in range(rows)]
    ways = [[0] * cols for _ in range(rows)]

    best[-1][-1] = grid[-1][-1]
    ways[-1][-1] = 1

    for i in range(rows - 1, -1, -1):
        for j in range(cols - 1, -1, -1):
            if i == rows - 1 and j == cols - 1:
                continue

            value = grid[i][j]
            if value is None:
                continue

            minimum = None
            count = 0

            if i + 1 < rows and best[i + 1][j] is not None:
                minimum = best[i + 1][j]
                count = ways[i + 1][j]

            if j + 1 < cols and best[i][j + 1] is not None:
                candidate = best[i][j + 1]
                if minimum is None or candidate < minimum:
                    minimum = candidate
                    count = ways[i][j + 1]
                elif candidate == minimum:
                    count += ways[i][j + 1]

            if minimum is not None:
                best[i][j] = value + minimum
                ways[i][j] = count

    if best[0][0] is None:
        return None

    moves = []
    i = j = 0

    while i != rows - 1 or j != cols - 1:
        if (
            i + 1 < rows
            and best[i + 1][j] is not None
            and best[i][j] == grid[i][j] + best[i + 1][j]
        ):
            moves.append("D")
            i += 1
        else:
            moves.append("R")
            j += 1

    return [best[0][0], ways[0][0], "".join(moves)]

