def solve(pattern: str, text: str) -> bool:
    tokens = []
    i = 0
    while i < len(pattern):
        ch = pattern[i]
        if ch == "\\":
            i += 1
            tokens.append(("lit", pattern[i]))
        elif ch == "*":
            if not tokens or tokens[-1][0] != "star":
                tokens.append(("star", ""))
        elif ch == "?":
            tokens.append(("any", ""))
        else:
            tokens.append(("lit", ch))
        i += 1

    m = len(text)
    dp = [False] * (m + 1)
    dp[0] = True

    for kind, value in tokens:
        next_dp = [False] * (m + 1)
        if kind == "star":
            seen = False
            for j in range(m + 1):
                seen = seen or dp[j]
                next_dp[j] = seen
        elif kind == "any":
            for j in range(1, m + 1):
                next_dp[j] = dp[j - 1]
        else:
            for j in range(1, m + 1):
                next_dp[j] = dp[j - 1] and text[j - 1] == value
        dp = next_dp

    return dp[m]

