def solve(query: str) -> dict[str, list[str]]:
    def decode(text: str) -> str:
        hexdigits = "0123456789abcdefABCDEF"
        out = bytearray()
        i = 0
        n = len(text)

        while i < n:
            ch = text[i]
            if ch == "+":
                out.append(0x20)
                i += 1
            elif (
                ch == "%"
                and i + 2 < n
                and text[i + 1] in hexdigits
                and text[i + 2] in hexdigits
            ):
                out.append(int(text[i + 1:i + 3], 16))
                i += 3
            else:
                out.extend(ch.encode("utf-8"))
                i += 1

        return bytes(out).decode("utf-8", "replace")

    if query.startswith("?"):
        query = query[1:]

    result: dict[str, list[str]] = {}

    for piece in query.split("&"):
        if piece == "":
            continue

        name, separator, value = piece.partition("=")
        decoded_name = decode(name)
        decoded_value = decode(value) if separator else ""

        result.setdefault(decoded_name, []).append(decoded_value)

    return result

